window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-principle|ep-04|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点三：教育目的的确立依据", "no": 1, "q": "在现代社会中，各个不同政治制度的国家，其教育目的的制定应首先适应它的（　）", "opts": ["政治制度", "科技水平", "经济基础", "文化传统"], "a": 0, "exp": "此题考查教育目的的确立依据。一国教育的性质是由其政治制度决定的，其教育目的首先适应的也是它的政治制度。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点三：教育目的的确立依据", "no": 2, "q": "教育目的不是固定的，即便对一个国家而言，也会根据不同阶段社会的发展情况，制定不同时期的教育目的。以下关于影响教育目的演变的因素，表述最全面的是（　）", "opts": ["时代与社会发展的需要，个体身心发展的特点与需要，社会政治、经济、文化的需要", "时代与社会发展的需要，个体身心发展的特点与需要，教育内部的需要", "社会生产和科技发展对人才的需要，社会政治、经济、文化的需要，教育内部的需要", "时代与社会发展的需要，个体身心发展的特点与需要，社会生产和科技发展对人才的需要"], "a": 1, "exp": "此题考查教育目的的确立依据。A、C选项中的“社会政治、经济、文化的需要”与D选项中的“社会生产和科技发展对人才的需要”均寓于“时代与社会发展的需要”之中，因此B选项的表述是最全面的。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点四：历年的教育目的", "no": 1, "q": "1958年9月，中共中央、国务院发布了《关于教育工作的指示》，提出了党的教育方针和教育目的，即“教育为无产阶级政治服务，（　）”。（　）", "opts": ["教育与工农群众相结合", "教育与阶级斗争相结合", "教育与生产劳动相结合", "教育与思想改造相结合"], "a": 2, "exp": "此题考查教育文件。1958年9月，中共中央、国务院发布了《关于教育工作的指示》，提出了党的教育方针和教育目的，即“教育为无产阶级政治服务，教育与生产劳动相结合”。A、B、D选项均为干扰项。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点四：历年的教育目的", "no": 2, "q": "2021年新修订的《中华人民共和国教育法》在原来规定的教育方针上新增加了（：．）内容。（　）", "opts": ["美育.", "国防教育", "科学技术教育", "劳动教育"], "a": 3, "exp": "此题考查教育文件。1995年《中华人民共和国教育法》要求培养德、智、体等方面全面发展的社会主义事业的建设者和接班人。2015年《中华人民共和国教育法》要求培养德、智、体、美等方面全面发展的社会主义建设者和接班人。2021年《中华人民共和国教育法》要求培养德智体美劳全面发展的社会主义建设者和接班人，在原有基础上加人了劳动教育。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点五：教育目的的精神实质", "no": 1, "q": "关于我国教育目的的精神实质，以下说法错误的是（　）", "opts": ["坚持社会主义方向，是我国教育目的的根本特点", "全面发展与个性发展是矛盾的", "培养劳动者是社会主义教育目的的总要求", "社会主义的教育质量标准是提高全民族的素质"], "a": 1, "exp": "此题考查教育目的的精神实质。A、C、D选项说法正确。人的全面发展也是指人的个性的充分的、自由的发展，二者不矛盾。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点六|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点六：全面发展教育", "no": 1, "q": "在当下教育中，我们倡导劳动教育，下列不属于劳动教育的主要实施范畴的是（　）", "opts": ["服务性劳动", "生产劳动", "日常生活劳动", "体验式劳动"], "a": 3, "exp": "此题考查劳动教育的主要内容。我国劳动教育新课标中明确规定我国劳动教育的主要内容包含服务性劳动、生产劳动、日常生活劳动，不包括体验式劳动。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点六|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点六：全面发展教育", "no": 2, "q": "学生通过体育活动能够获得愉悦的情感体验，这说明体育具有（　）", "opts": ["思想性", "技能性", "娱乐性", "竞技性"], "a": 2, "exp": "此题考查体育。性和竞技性无关。因此，答案选C。深联系微信193163788日", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 146}},
  {"id": "kc|edu-principle|ep-04|知识点六|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点六：全面发展教育", "no": 3, "q": "下列关于美育和艺术教育的关系，说法正确的是（　）", "opts": ["美育就是艺术教育", "艺术教育就是吹拉弹唱", "艺术教育包括美育", "艺术教育是实施美育的重要途径"], "a": 3, "exp": "此题考查美育和艺术教育的关系。A.修改：艺术教育中有很大一部分是艺术技巧的教育，并以培养人的艺术感受力与创造力为主。审美教育却不一定涉及艺术技巧的培养，对艺术的感受力的培养是为审美主体形成完善的结构和健康人格服务的。二者不同。B.修改：广义的艺术教育强调普及艺术的基础知识和基本原理，通过对优秀艺术作品的评价与欣赏，来提高人们的审美修养和艺术鉴赏力，培养人们健全的审美心理结构，并不单指吹拉弹唱。C.修改：美育包括艺术教育，艺术教育是美育的重要组成部分。D.艺术教育是实施美育的主要途径。由于艺术具有审美认知、审美教育、审美娱乐等独特的功能和作用，具有以情感人、潜移默化、寓教于乐等特点，因此艺术教育成为审美教育的主要内容和主要方式。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 146}},
  {"id": "kc|edu-principle|ep-04|知识点六|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点六：全面发展教育", "no": 4, "q": "20世纪末，我国教育界开始倡导素质教育。关于素质教育，下列说法正确的是（　）", "opts": ["素质教育就是不要考试；特别是不要百分制考试", "素质教育就是多开展课外活动，多上文体课", "素质教育就是为了克服应试教育的端提出的教育", "素质教育就是不要学生刻苦学习，“减负”就是不给或少给学生留课后作业"], "a": 2, "exp": "此题考查素质教育。A.修改：素质教育不代表取消考试，考试作为评价的手段，是衡量、激励学生发展的尺度之一。B.修改：教育培养人的基本途径是教学，学生的基本任务是在接受人类文化精华的过程中获得发展。这就决定了素质教育的主渠道是教学，主阵地是课堂。C.克服应试教育的端是素质教育提出的背景与原因。√D.修改：素质教育要求学生刻苦学习，因为只有刻苦学习，才能真正体会到努力与成功的关系，才能形成日后所需要的克服困难的勇气、信心和毅力。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 146}},
  {"id": "kc|edu-principle|ep-04|知识点六|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点六：全面发展教育", "no": 5, "q": "关于全面发展，以下说法不正确的是（　）", "opts": ["五育”之间不可分割，不可相互代替", "五育”之间并列实施或独立实施", "全面发展并不是指人的各方面“平均发展", "全面发展不是忽视人的个性发展"], "a": 1, "exp": "此题考查全面发展教育。A、C、D选项说法正确。“五育”之间既相对独立，不可相互替代，又相互联系、相互促进。它们在实施过程中会有交叉和融合，不是并列实施或独立实施的。当下我国提出了一个新概念，就是“五育”融合。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 146}},
  {"id": "kc|edu-principle|ep-05|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 1, "q": "教育制度的核心是（　）", "opts": ["学校教育制度", "成人教育制度", "教育管理制度", "业余教育制度"], "a": 0, "exp": "此题考查学校教育制度。学校教育制度（学制）是教育制度的核心。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 2, "q": "下列不属于学制的要素的是（：（　）", "opts": ["学校类型", "学校级别", "学校结构", "学校规模"], "a": 3, "exp": "此题考查学制的要素。学制的要素主要包括学校类型、学校级别和学校结构。学校规模不属于学制的要素。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 3, "q": "学制规定了各级各类学校的性质、任务、人学条件、修业年限以及学校之间的（　）", "opts": ["主导与辅助关系", "领导与从属关系", "合作与竞争关系", "衔接与分工关系"], "a": 3, "exp": "此题考查学制的概念。学制是一个国家或地区各级各类学校的系统及其管理规则的总称。它规定着各级各类学校的性质、任务、人学条件、修业年限以及学校之间的衔接与分工关系。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 4, "q": "世界各国的学制存在着差异，但在人学年龄、中小学分段等方面却有着较高的一致性。这说明建立学制要以（　）为依据。（　）", "opts": ["社会政治经济制度", "生产力发展水平", "青少年身心发展规律", "民族和文化传统"], "a": 2, "exp": "此题考查学校教育制度确立的依据。学制的确立受学生身心发展规律和年龄特征的制约。青少年身心发展具有一定的规律，成长经历不同的年龄阶段各有其年龄特征，在确立学制时必须适应这种特征。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 5, "q": "根据《中华人民共和国教育法》规定，下列不属于我国基本教育制度的是（　）", "opts": ["义务教育制度", "职业教育制度", "学业证书制度", "教师资格制度"], "a": 3, "exp": "此题考查我国基本教育制度。《中华人民共和国教育法》规定的是我国比较宏观的教育制度，A、B、C选项都属于宏观的制度。教师资格制度属于教师管理方面的一个制度，一般在《中华人民共和国教师法》中规定，不属于宏观制度建设的内容。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点一|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点一：教育制度与学制的概念", "no": 6, "q": "关于教育制度的特点，下列说法不正确的是（　）", "opts": ["教育制度具有发展性，不同国家的教育制度会随政治、经济和文化的发展而变化", "教育制度具有强制性，国家通过法律和政策保障其执行，个人必须无条件服从", "教育制度具有系统性，包括学前教育、基础教育、高等教育等相互衔接的组成部分", "教育制度具有相对稳定性，虽然会调整优化，但核心框架不会频繁变动"], "a": 1, "exp": "此题考查教育制度的特点。A.教育制度会随社会的发展而变化。B.修改：教育制度具有强制性（如义务教育），强制性的核心是保障受教育权，但个人在法律框架内有教育路径选择权（如普通高中／中等职业教育），即适应和遵守制度。“无条件服从”体现了绝对强制，不符合我国保障人权的特点。此题为选非题。√C.教育制度是一个有机整体，各阶段相互衔接。D.教育制度需保持相对稳定，避免频繁变动影响教育质量。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点二：学制的类型", "no": 1, "q": "历史课上，在讲到“学生结束在初级中学的学习，可升人两年制中等职业技术学校，也可参加全国统一的高等中学人学考试，升人高级中学学习”时，老师提问：这是哪种学制类型？（　）", "opts": ["单轨制", "分支型学制", "三轨制", "双轨制"], "a": 1, "exp": "此题考查学制的类型。学制的类型总结表类型特点单轨制所有学生可进人同一种学制体系。这一体系不分叉，形成小学一中学一大学自下而上的结构学制分为并行的两轨：一轨自上而下，针对贵族子弟，其结构是大学一中学；另一轨自下而上，针对双轨制平民子弟，其结构是小学一职业学校分支型学制介于双轨制和单轨制之间，学制前段并轨，学制后段分叉分支型学制的特点：（1）学制前段并轨。小学、初中阶段是单轨，所有学生一律人学。（2）学制后段分叉。初中阶段后，依据学生成绩和实际需要进人各种类型的学校，分叉后的学校上通高等学校，下达初等学校，左通中等专业学校，右达中等职业技术学校，上下左右畅通无阻。结合题干应选择分支型学制。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点二：学制的类型", "no": 2, "q": "双轨制形成于18一19世纪的西欧，其中一轨是学术性的，另一轨是职业性的。以下描述正确的是）（　）", "opts": ["两轨均发端于高等教育，是自上而下的", "两轨均发端于高等教育，是自下而上的", "学术性一轨是自上而下，职业性一轨是自下而上", "学术性一轨是自下而上，职业性一轨是自上而下"], "a": 2, "exp": "此题考查学制的类型。双轨学制有两个平行的系统：一轨自上而下，其结构是大学一中学系统，这一轨具有学术性；另一轨自下而上，其结构是小学一职业学校系统，这一轨具有职业性。依据知识点二第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点二：学制的类型", "no": 3, "q": "单轨制最早产生于美国，长期以来之所以没有发生重大变化，被世界许多国家先后采用，是因为它有利于（　）", "opts": ["适应不同民众的需要", "教育的逐级普及", "教育资源的均衡分配", "保障教育质量"], "a": 1, "exp": "此题考查单轨制。A.该选项不是单轨制被广泛采用的主要原因。分支型学制更加灵活，也能适应不同民众的需要。B.单轨制为不同阶层的学生提供了平等的受教育机会，有利于教育的逐级普及，使更多人能够接受系统的教育。√C.教育资源的分配受到多种因素的影响，采用单轨制并不意味着教育资源能均衡分配。D.教育质量与学制类型无直接关系，单轨制本身并不能直接保障教育质量。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 147}},
  {"id": "kc|edu-principle|ep-05|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点二：学制的类型", "no": 4, "q": "下列关于我国现行学制的描述，正确的是（　）", "opts": ["我国基础教育阶段实行典型的双轨制，普通教育和职业教育体系互不相通", "我国学制结构上属于单轨制，普通教育与职业教育完全融合在同一所学校内", "我国学制属于分支型学制，义务教育阶段之后开始逐步分化，普通教育与职业教育既有分流又有衔接", "我国学制是纯粹的双轨制在高中阶段的体现，职业高中学生不能升人普通高校"], "a": 2, "exp": "此题考查我国现行学制。A.修改：我国现行学制不是双轨制。B.修改：我国现行学制不是单轨制（如美国），职业教育与普通教育并非完全在同一学校内融合。C.分支型学制（苏联型）特征是在义务教育阶段单轨，之后分流，但保留互通渠道。我国现行学制与之类似，义务教育后学生可进人普通高中或中职，两类教育可通过考试等方式衔接。√D.修改：我国职业高中学生可通过对口升学、普通高考等方式升人高校，并非完全封闭。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 1, "q": "下列对我国现行学制基本结构的描述，正确的是（　）", "opts": ["学前教育、初等教育、中等教育、高等教育", "普通教育、职业教育、师范教育、高等教育", "基础教育、高等教育、职业教育、技术教育", "基础教育、师范教育、高等教育、职业教育"], "a": 0, "exp": "此题考查我国学制的基本结构。A.根据《中华人民共和国教育法》，国家实行“学前教育、初等教育、中等教育、高等教育的学校教育制度”。这是我国学制在法律层面最权威、最标准的纵向阶段划分。√B/D.修改：师范教育是高等教育中的一种专业教育，不能与“高等教育”并列。C.修改：技术教育是职业教育的一部分，也不宜与职业教育并列。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 2, "q": "下列关于义务教育的表述，错误的是（　）", "opts": ["普及教育就是义务教育", "义务教育具有强制性", "高中教育会逐渐义务化", "学前教育不属于义务教育"], "a": 0, "exp": "此题考查义务教育。A.修改：普及教育更侧重于国家对教育的普遍提供，但不具有强制性和免费性，而义务教育在此基础上强调了教育的强制性、免费性以及对学生基本能力和素质的培养。所以，义务教育体现了普及教育，但不能将二者完全等同。此题为选非题。√B.义务教育的三个特征是免费性、强制性和普及性。C.义务教育发展的趋势是既向学前教育延长，又向高中教育延长。所以，高中教育发展的趋势就是逐渐义务化。D.目前我国学前教育已经基本实现普及教育，但还不属于义务教育。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 3, "q": "关于我国的学前教育，下列说法正确的是（　）", "opts": ["既属于义务教育，又属于强制教育", "既属于基础教育，又属于国民教育", "既属于终身教育，又属于义务教育", "既属于终身教育，又属于强制教育"], "a": 1, "exp": "此题考查学前教育。学前教育是终身教育中的一环，属于国民教育和基础教育，但在我国目前还不属于义务教育，也不是强制性的。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 4, "q": "关于我国的职业教育，下列说法正确的是（　）", "opts": ["既属于普通教育，又属于技能教育", "既属于学历教育，又属于技能教育", "既属于职业教育，又属于高等教育", "既属于免费教育，又属于义务教育"], "a": 1, "exp": "此题考查职业教育。A.修改：职业教育注重培养学生的职业技能和实践能力。与以传授基础知识为主的普通教育不同，职业教育以培养职业技能为核心。B.职业教育包括中等职业教育、高等职业教育等不同层次，学生通过学习可以获得相应的学历证书，同时职业教育的核心是培养学生掌握特定职业所需的技能，所以它既属于学历教育，又属于技能教育。√C.修改：职业教育包括中等职业教育、高等职业教育等不同层次。高等职业教育属于高等教育的一部分，但不能说职业教育属于高等教育。D.修改：在我国，学生接受职业教育需要缴纳学费，虽然国家有一些资助政策和奖学金制度，但职业教育不是免费教育和义务教育。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 5, "q": "关于我国学制，以下说法正确的是（　）", "opts": ["我国学校教育制度不包括学前教育", "我国普通教育不包括高等教育", "我国基础教育不包括普通高中教育", "我国义务教育不包括普通高中教育"], "a": 3, "exp": "此题考查我国学制。A.修改：我国实行学前教育、初等教育、中等教育、高等教育的学校教育制度。B.修改：普通教育主要包括普通中小学教育和普通高等学校教育。C.修改：基础教育主要分为学前教育、义务教育、普通高中教育。D.目前我国九年制义务教育包括小学和初中，不包括普通高中教育。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点三|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点三：我国的学制", "no": 6, "q": "在我国现代学制中，我国中学常见类型有（　）", "opts": ["普通中学、职业中学、综合中学", "文科中学、理科中学、综合中学", "文法中学、实科中学、技术中学", "普通中学、重点中学、特色中学"], "a": 0, "exp": "此题考查我国中学的类型。欧洲才分文科中学（文法中学）与理学中学（实科中学）。我国有技术中学，属于职业中学的一种，在我国叫作“中等职业学校”（简称“中职”）。我国的重点中学属于普通中学，二者同属一类。我国有特色中学，它是在普通中学基础上，通过聚焦某一领域（如外语、科技、艺术、体育等）形成的办学类型，其核心是在完成国家基础课程的同时，发展特色项目。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点四：历年的学制", "no": 1, "q": "下列不属于《中国教育现代化2035》提出的基本理念的是（　）", "opts": ["以德为先，终身学习", "面向人人，全面发展", "因材施教，知行合一", "面向乡村，立足当下"], "a": 3, "exp": "D热点+推理题此题考查教育文件。《中国教育现代化2035》提出的八大理念有：以德为先，全面发展，面向人人，终身学习，因材施教，知行合一，融合发展，共建共享。本题亦可采用推理法作答。《中国教育现代化2035》是一个战略性文件，深联系微信19316378日日是乡村，不能体现全国这一整体；“立足当下”针对的是目前的情况，没有体现未来。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点四：历年的学制", "no": 2, "q": "中共中央办公厅、国务院办公厅印发的《关于构建优质均衡的基本公共教育服务体系的意见》要求“发达地区不得从中西部地区、东北地区抢挖优秀校长和教师”。其旨在（　）", "opts": ["促进区域协调发展", "推动城乡整体发展", "加快校际均衡发展", "保障群体公平发展"], "a": 0, "exp": "此题考查教育文件。“发达地区不得从中西部地区、东北地区抢挖优秀校长和教师”是《关于构建优质均衡的基本公共教育区、东北地区”相对来说是教育资源匮乏的地区，不得从这些地区“抢挖优秀校长和教师”说明要保护当地教育资源，目的是促进区域协调发展。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点四：历年的学制", "no": 3, "q": "以下不属于《中国教育现代化2035》所提出的主要发展目标的是（　）", "opts": ["普及有质量的学前教育", "实现优质均衡的义务教育", "全面普及普高教育", "职业教育服务能力显著提升"], "a": 2, "exp": "此题考查教育文件。《中国教育现代化2035》所提出的2035年主要发展目标：建成服务全民终身学习的现代教育体系、普及有质量的学前教育、实现优质均衡的义务教育、全面普及高中阶段教育、职业教育服务能力显著提升、高等教育竞争力明显提升、残疾儿童少年享有适合的教育、形成全社会共同参与的教育治理新格局。C选项“全面普及普高教育”不等于“全面普及高中阶段教育”。此题为选非题，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 148}},
  {"id": "kc|edu-principle|ep-05|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点四：历年的学制", "no": 4, "q": "1993年，《中国教育改革和发展纲要》提出建立“以政府办学为主体、社会各界共同办学”的体制。这一改革主要针对的是（　）", "opts": ["教育机会均等问题", "教育供给单一化问题", "教育质量标准化问题", "教育评价功利化问题"], "a": 1, "exp": "此题考查教育文件。改革前，政府包揽办学导致供给单一，1993年办学体制改革旨在打破垄断，形成多元办学格局。A、C、D选项虽与教育改革相关，但并非此次办学体制改革主要针对的问题。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点四：历年的学制", "no": 5, "q": "《教育强国建设规划纲要（2024一2035年）》提出的战略目标中，到2027年要达成的是（：（　）", "opts": ["建成教育强国", "教育强国建设取得重要阶段性成效", "学习型社会全面形成", "基础教育普及水平和质量稳居世界前列"], "a": 1, "exp": "此题考查教育热点文件。《教育强国建设规划纲要（2024一2035年）》指出，到2027年，教育强国建设取得重要阶段性成效；到2035年，建成教育强国，基础教育普及水平和质量稳居世界前列，学习型社会全面形成。此题亦可使用推理法作答，A、C、D选项的表述更像最终目标，不像阶段性目标，题干问的不是2035年的最终目标，而是2027年的阶段性目标，所以B选项的表述更适合。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 1, "q": "习近平总书记在2024年两会上指出：“我们要实实在在地把职业教育搞好，要树立工匠精神，把第一线的大国工匠一批一批培养出来。”以下关于职业教育的说法，错误的是（　）", "opts": ["推动专业设置、人才培养与市场需求对接", "深化产教融合、校企合作，延伸办学空间", "推动职普融通，增强职业教育的适应性", "职业教育与普通教育的目标与地位均不同"], "a": 3, "exp": "此题考查职业教育。职业教育以就业为目标，旨在让受教育者获得某种职业或生产劳动所需要的职业知识、职业技能和职业道德；普通教育以升学为目标，以基础科学知识为主要教学内容，二者的培养目标不同。2022年新修订的《中华人民共和国职业教育法》规定职业教育与普通教育具有同等重要的地位，D选项说法错误。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点五|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 2, "q": "习近平总书记指出，在全面建设社会主义现代化国家新征程中，职业教育前途广阔、大有可为。以下不属于促进我国职业教育发展的措施的是（　）", "opts": ["必须坚持党的领导，发挥中国特色社会主义制度优势", "遵循“一带一路”倡议，提高职业教育开放水平", "职业学校的教育与职业培训并重", "职业教育以政府为主，地方辅助"], "a": 3, "exp": "此题考查对现代教育制度改革的理解。各地的经济发展类型不同，支柱企业也各不相同，职业教育如果以政府为主，会过于整齐划一，不够突出地方的灵活性。因此，我国职业教育实行政府统筹、分级管理、地方为主、行业指导、校企合作、社会参与。D选项说法错误。此题为选非题，因此，答案选D。·非正规教育的复兴及其对正规教育的影响。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点五|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 3, "q": "非正规教育的复兴及其对正规教育的影响关于非正规教育，说法正确的一项是（　）", "opts": ["非正规教育是正规教育的补充与丰富", "非正规教育是没有组织性的教育", "非正规教育会扰乱正规教育", "非正规教育正在加重学校的负担"], "a": 0, "exp": "此题考查非正规教育。A.非正规教育（如职业培训、社区教育、在线学习平台等）通常具有灵活性、实用性和多样性，它在学习内容、时间和方式上补充了正规学校系统的不足，丰富了终身教育的体系，是现代教育生态的重要组成部分。√B.修改：非正规教育虽然没有正规教育那样严格的学制、课程和认证体系，但并非没有组织性。它通常有明确的目标、教学计划和组织形式（如培训班、讲座、网络课程等），只是组织形式相对灵活。C.修改：非正规教育并不会扰乱正规教育。二者在功能上互补，共同服务于个人的终身学习和社会的教育需求。正规教育提供系统化的基础知识和学历认证，非正规教育则提供技能提升、兴趣培养等个性化学习机会。D.修改：非正规教育并不会必然加重学校的负担。相反，它可以通过分担部分教育职能（如职业技能培训、成人继续教育），缓解正规学校的压力。二者可以通过合作实现资源共享和功能互补。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点五|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 4, "q": "为适应市场对复合型人才的需求，职场人小赵利用业余时间，在多个线上平台学习不同领域的课程。这些课程有的来自知名高校，有的出自行业专家，内容丰富多样。学习时间和进度由小赵自主掌控。小赵的这种学习未体现（　）", "opts": ["学习化社会的来临", "终身学习的需要", "非正规教育的优势", "正规教育的加持"], "a": 3, "exp": "此题考查现代教育制度的改革。A.学习化社会强调学习成为社会的基本特征，人们可以随时随地进行学习。题干中，小赵利用业余时间在线上平台进行学习，体现了学习化社会中学习的便利性和普遍性。B.终身学习是指人的一生都要不断地学习，以适应社会的发展和个人成长的需要。题干中，小赵作为职场人，为适应市场需求，利用业余时间学习不同领域的课程，体现了终身学习的理念。C.非正规教育是指在正规教育系统外进行的有组织、有计划的教育活动，具有灵活性。题干中，小赵通过多个线上平台学习不同领域的课程，且学习时间和进度都由自己掌控，体现了非正规教育的优势。D.正规教育是指有组织、有体系、有固定课程和师生结构的制度化教育（如传统的学校教育）。题干中，小赵利用业余时间在线上自主学习，恰恰摆脱了正规教育的束缚，没有体现“正规教育的加持”。此题为选非题。√·高中的多样化、特色发展及其与大学的衔接。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 149}},
  {"id": "kc|edu-principle|ep-05|知识点五|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 5, "q": "高中的多样化、特色发展及其与大学的衔接。关于我国普通高中发展的特点，说法不正确的一项是（　）", "opts": ["普惠化", "义务化", "特色化", "多样化"], "a": 1, "exp": "此题考查我国高中发展特点。目前我国普通高中教育尚未纳人义务教育范畴，B选项说法错误。我国普通高中具有普惠化、特色化、多样化、加强高中与大学的衔接等特点。此题为选非题，因此，答案选B。·高等教育的大众化。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 6, "q": "高等教育的大众化·依照美国著名社会学家马丁·特罗对高等教育发展阶段的划分，高等教育发展分为三个阶段，其中不包括（　）", "opts": ["精英化阶段", "终身化阶段", "大众化阶段", "普及化阶段"], "a": 1, "exp": "此题考查高等教育发展阶段论。马丁·特罗将高等教育的发展划分为精英化高等教育阶段（毛人学率在15%以下）大众化高等教育阶段（毛人学率为15%～50%）和普及化高等教育阶段（毛人学率在50%以上），不包括终身化阶段。此题为选非题，因此，答案选B。深联系微信193163788日", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 7, "q": "回顾我国高等教育的发展历程，2003年、2013年和2024年的高等教育毛人学率分别是17%、34.5%和8%。根据马丁·特罗的高等教育发展阶段论，这三年我国分别处于（）高等教育阶段。（　）", "opts": ["精英化、大众化、普及化", "大众化、大众化、普及化", "精英化、普及化、大众化", "大众化、大众化、大众化"], "a": 1, "exp": "此题考查高等教育发展阶段论。马丁·特罗将高等教育的发展划分为精英化高等教育阶段（毛人学率在15%以下）大众化高等教育阶段（毛人学率为15%～50%）和普及化高等教育阶段（毛人学率在50%以上）。据此，我国2003年、2013年和2024年分别处于大众化、大众化和普及化高等教育阶段。因此，答案选B。·终身教育体系的建构。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 8, "q": "终身教育体系的建构·《学会生存一—教育世界的今天和明天》这篇报告中特别强调的两个基本理念是（　）", "opts": ["终身教育和学习型社会", "民主教育和全民教育", "终身教育和民主教育", "全民教育和学习型社会"], "a": 0, "exp": "此题考查《学会生存—教育世界的今天和明天》。《学会生存一教育世界的今天和明天》标志着联合国教科文组织首次提出终身教育理念，主张建设学习型社会。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 9, "q": "《学会生存一—教育世界的今天和明天》指出，第二次世界大战结束以来，各国教育面临社会发展的新需求与挑战，存在三种普遍流行的现象，其中不包括（　）", "opts": ["教育先行", "培养完人", "社会拒绝使用学校毕业生", "为未知社会培养新人"], "a": 1, "exp": "此题考查《学会生存一教育世界的今天和明天》。“二战”结束以来各国教育面临社会发展的新需求与挑战，存在三种普遍流行的现象，即“教育先行”“为未知社会培养新人”“社会拒绝使用学校毕业生”。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 10, "q": "联合国教科文组织在《教育一—财富蕴藏其中》报告中提出面向21世纪教育的四大支柱是学会认知、学会做事、学会共同生活和（　）", "opts": ["学会关心", "学会生存", "学会创造", "学会交往"], "a": 1, "exp": "此题考查《教育—财富蕴藏其中》。《教育一—财富蕴藏其中》中指出，面向21世纪教育的四大支柱，就是要培养学生四种本领：学会认知、学会做事、学会共同生活、学会生存。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 11, "q": "联合国教科文组织1995年在《教育一—财富蕴藏其中》报告中指出，基础教育务必以“学会认知、学会做事、学会共同生活、学会生存”为支柱。在此基础上，2013年又增加一条（）的价值诉求。（　）", "opts": ["学会创新", "学会改变", "学会做人", "学会创造"], "a": 1, "exp": "此题考查《教育一财富蕴藏其中》。2013年联合国教科文组织在《教育一财富蕴藏其中》报告中增加“学会改变”的价值诉求。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|12", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 12, "q": "终身教育思想始于20世纪20年代，于20世纪60年代在国际上流行，特别是《终身教育引论》（保罗·朗格朗）《教育一财富蕴藏其中》和《学会生存一—教育世界的今天和明天》问世后，成为指导未来教育的时代理念。下列关于终身教育的特征，表述错误的是（　）", "opts": ["终身教育重点关注正规教育之后的成人教育", "终身教育从纵的方面寻求教育的连续性和一贯性", "终身教育从横的方面寻求教育的统合", "终身教育与拔尖主义的教育相反，具有普遍性，主张教育的民主化"], "a": 0, "exp": "此题考查终身教育。终身教育是人一生各阶段所受各种教育的总和。终身教育关注所有时期的教育，并没有侧重某一时期。A选项说法错误。此题为选非题，因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|13", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 13, "q": "下列说法中，与终身教育相悖的是（　）", "opts": ["学校教育仍然是终身教育的重要基础", "应打破教育者与受教育者的绝对界限", "最终目标是提升个人竞争力", "应消除年龄、职业等对学习机会的限制"], "a": 2, "exp": "此题考查终身教育。A.学校教育是个体系统学习的起点，为终身学习奠定知识和能力基础，是终身教育体系的重要组成部分。，B.终身教育倡导学习型社会，认为每个人既是教育者也是受教育者，反对传统的单向灌输式教育模式。C.终身教育的最终目标是促进人的全面发展，而非单纯追求社会地位或经济利益（功利化教育的表现）。此题为选非题。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 150}},
  {"id": "kc|edu-principle|ep-05|知识点五|14", "bank": "kc", "subj": "edu-principle", "ch": "ep-05", "chName": "第五章 教育制度", "sec": "知识点五：教育制度的发展趋势", "no": 14, "q": "《中国教育现代化2035》提出，到2035年，总体实现教育现代化，迈入教育强国行列。《中国教育现代化2035》中关于“终身教育”的表述是（　）", "opts": ["开始准备构建的终身教育", "建成服务全民终身学习的现代教育体系", "使终身教育成为一项强制性的义务", "健全充满活力的教育体制"], "a": 1, "exp": "此题考查终身教育与《中国教育现代化2035》。A.依据常识我国早就在建立终身教育体系，该文件的目标是在该时间节点建成体系，而非“开始准备”B.文件的核心目标之一正是“建成服务全民终身学习的现代教育体系”，强调构建覆盖全民、贯穿终身、资源丰富的学习型社会。√C.文件强调的是提供终身学习的机会和体系，而非将其作为一项强制性的“义务”。终身教育是权利和机会，并非法律强制的义务。D.该表述是整体教育改革的方针，并非专门针对“终身教育”的具体表述，属于答非所问。深联系微信1931637日8日", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 151}},
  {"id": "kc|edu-principle|ep-06|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点一：课程概念", "no": 1, "q": "任何社会文化中的课程，事实上都是该社会文化的反映，学校教育的职责是要再生产对下一代有用的知识和价值。这反映的课程定义为：课程即（　）", "opts": ["社会改造的过程", "教学科目", "文化再生产", "学习经验"], "a": 2, "exp": "此题考查课程的概念。鲍尔斯等人认为，课程就是从某种社会文化里选择出来的材料，学校教育要再生产对下一代有用的知识与价值。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 151}},
  {"id": "kc|edu-principle|ep-06|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点一：课程概念", "no": 2, "q": "按照美国学者古德莱德的观点，课程可以分为五个层面，除理想的课程、正式的课程、领悟的课程外，还有（　）", "opts": ["生活的课程和经验的课程", "运作的课程和经验的课程", "隐性的课程和运作的课程", "隐性的课程和生活的课程"], "a": 1, "exp": "此题考查古德莱德的课程分类。古德莱德将课程分为五种：理想的课程、正式的课程、领悟的课程、实行的课程（运作的课程）经验的课程。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 151}},
  {"id": "kc|edu-principle|ep-06|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点一：课程概念", "no": 3, "q": "课程的定义较为丰富，学者们普遍认为中国的“六艺”与古希腊的“七艺”的定义方式都属于（　）", "opts": ["课程即教学科目", "课程即学习经验", "课程即文化再生产", "课程即社会改造的过程"], "a": 0, "exp": "此题考查课程的概念。“六艺”与“七艺”是分科进行教学，属于教学科目。“课程即教学科目”是最普遍、最常识化的课程定义。广义的课程是指学生所学的全部学科以及在教师指导下的各种活动的总称；狭义的课程是指一门学科或一类课程。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点一：课程概念", "no": 4, "q": "目前我国基础教育倡导培养学生的核心素养。从课程论的角度看，该核心素养属于古德莱德课程层次理论中的（　）", "opts": ["理想的课程", "正式的课程", "实行的课程", "经验的课程"], "a": 1, "exp": "B理解题此题考查课程的类型。核心素养明确学生应具备的必备品格和关键能力，从中观层面深人回答“立什么德、树什么人”的根德莱德课程层次理论中正式的课程。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点一：课程概念", "no": 5, "q": "王老师在讲解《桂林山水》一课时，并未完全按照教材内容授课，而是结合自己的旅行见闻和感悟，生动地拓展了桂林山水的文化内涵和地质特点。学生们被王老师的讲解深深吸引，并积极主动地分享自己游览过的自然景观。整个课堂氛围热烈，孩子们眼里有光，热情洋溢。这一教学场景主要体现的课程类型是（　）", "opts": ["①②③", "②③④", "③④5", "②④"], "a": 2, "exp": "此题考查古德莱德的课程分类。（1）领悟的课程：教师对课程的个性化理解与解读的课程。题干中，王老师“结合自已的旅行见闻和感悟，生动地拓展了桂林山水的文化内涵和地质特点”，体现了其对课程内容的独特领悟，属于领悟的课程。（2）实行的课程：教师在课堂上实际实施的课程。题干中，王老师引导学生进行的这场“分享”就是实际实施的课程，属于实行的课程。（3）经验的课程：学生实际感受和体验到的，并使学生的经验发生改变的课程。题干中，学生在分享中获得了“眼里有光，热情洋溢”的体验，属于经验的课程。（4）理想的课程：研究机构、学术团体和课程专家构想的课程，题干未体现。（5）正式的课程：由教育行政部门颁布实施的课程计划、教材等官方内容。题干中，王老师虽“未完全按照教材内容授课”，但“讲解《桂林山水》一课”本身源于教材中的正式的课程主题，与正式的课程有一定关联，但并非核心体现。题干的重点在于教师根据课堂情况调整后的课程实施和学生体验。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点二：课程理论流派", "no": 1, "q": "“学校课程中相关的真正中心，不是科学，不是文学，不是历史，不是地理，而是儿童本身的社会生活。”这一观点反映的课程理论是（　）", "opts": ["存在主义课程理论", "学科中心主义课程理论", "经验主义课程理论", "社会中心课程理论"], "a": 2, "exp": "此题考查经验主义课程理论。“不是科学，不是文学，不是历史，不是地理”说明不是学科中心主义课程论，B选项错误。题干的中心意思是学校课程要围绕儿童本身的社会生活，尽管提到了社会生活，但重点在“儿童本身”，A、D选项均没有体现。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点二：课程理论流派", "no": 2, "q": "某一课程理论反对与学生的经验、生活脱节，与社会现实脱离的课程；重视学生的本能、冲动和兴趣，并把学生现有的经验作为课程开发的起点。这一课程理论是（　）", "opts": ["知识中心课程理论", "学习者中心课程理论", "社会中心课程理论", "教学者中心课程理论"], "a": 1, "exp": "此题考查课程理论。点。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点二：课程理论流派", "no": 3, "q": "社会中心课程理论最核心的主张是（　）", "opts": ["课程应以学生的兴趣和需要为中心来组织", "课程应致力于传承人类文化遗产中的永恒知识", "课程应围绕社会问题和社会改造来设计，帮助学生适应并改造社会", "课程应以训练学生的形式思维和智力发展为根本目的"], "a": 2, "exp": "此题考查社会中心课程理论。A.学习者中心课程理论以学生的兴趣和需要为中心。B.知识中心课程理论流派中有一支是要素主义教育，主张课程来自人类文化遗产中的永恒知识。C.社会中心课程理论以社会问题为核心，依据社会需要来设计课程，使学生参与社会实践，培养其分析、解决实际问题的能力，批判和改造社会。√D.知识中心课程理论以训练学生的形式思维和智力发展为根本目的。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点二：课程理论流派", "no": 4, "q": "主张教育的目的是传递人类共同的文化遗产，训练智力，促进人的自我实现，学校的课程应该给学生提供分化的、有组织的经验，即知识。秉持这种观点的人在课程理论流派上倾向于（　）", "opts": ["学科中心课程理论", "社会中心课程理论", "活动中心课程理论", "后现代主义课程理论"], "a": 0, "exp": "A理解题此题考查课程理论流派。学科中心课程理论强调以学科知识为课程中心，严格按照每门学科的逻辑体系组织材料，并在此基础上进行分科教学，其代表是要素主义课程理论和永恒主义课程理论。题干中主张教育的目的是传递人类共同的文化遗产，学校的课程应教给学生知识，这体现了要素主义的课程观。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点二：课程理论流派", "no": 5, "q": "以下关于课程理论与代表人物的搭配，正确的是（：（　）", "opts": ["知识中心课程理论—布拉梅尔德——重视知识体系", "学习者中心课程理论——巴格莱—重视直接经验", "社会中心课程理论—罗杰斯—重视社会改造", "学科中心课程理论—布鲁纳—注重学科知识的学习"], "a": 3, "exp": "此题考查课程理论及其流派。A.修改：布拉梅尔德是社会中心课程理论的代表人物。B.修改：巴格莱主张知识中心，重视间接经验的学习。C.修改：罗杰斯主张学习者中心，注重直接经验的学习。D.布鲁纳是学科（知识）中心课程理论的代表人物，注重学科知识的学习。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 152}},
  {"id": "kc|edu-principle|ep-06|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 1, "q": "学校课程有多种类型，其中最有利于学生系统掌握人类所取得的经验和科学认识的课程是（　）", "opts": ["学科课程", "经验课程", "活动课程", "隐性课程"], "a": 0, "exp": "此题考查学科课程。课程的类型总结表学科课程根据各级各类学校培养目标和学生的发展水平，分门别类地从各学科中选择知识，并按照学科（同分科课程）的逻辑组织学科内容的课程活动课程以学生的兴趣、需要、经验、能力为基础，通过引导学生自己组织有目的的活动而编制的课程两门或两门以上的具有科际联系点的学科知识综合在一门课程中，但不打破相关课程综合程度较低原来的学科界限融合课程打破了学科界限，把有着内在联系的不同学科知识合并成一门学科的课程综合程度较高综合课程将各科教材依照性质归到各个领域，再将同一领域的各科教材加以组织和排广域课程综合程度更高列，进行系统教学的课程核心课程打破原有学科界限，围绕一些重大社会问题组织教学内容的课程综合程度最高必修课程国家、地方或学校规定的学生必须学习的课程，保证所有学生的基本学力选修课程依据不同学生的特点与发展方向，容许学生进行个人选择的课程国家课程由中央政府负责编制、实施和评价的课程起套课程公众号【研大]续表地方各级教育主管部门根据国家课程政策，充分利用地方课程资源而开发、设计、实施的课程地方课程以学校为课程编制主体，自主研发与实施的课程校本课程生本课程受，但可以将其看作校本课程的延伸显性课程课程方案中明确列出和有专门要求的课程隐性课程以内隐的、间接的方式呈现的课程基础型课程注重培养学生基础能力的课程形态研究型课程注重培养学生探究态度和能力的课程形态拓展型课程注重拓", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 2, "q": "开设人口教育课、环境教育课、闲暇与生活方式课等新课程，这些课程要融合历史、地理、化学、生物、物理等学科知识，这是（　）", "opts": ["综合课程", "活动课程", "学科课程", "相关课程"], "a": 0, "exp": "此题考查综合课程。综合课程是打破传统的学科课程的知识领域，组合相邻领域的学科构成一门学科的课程，其根本目的是克服学科课程分科过细的问题。人口教育课、环境教育课、闲暇与生活方式课等融合了多门学科的知识。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 3, "q": "从课程类型划分上看，核心课程属于（　）", "opts": ["学科课程", "活动课程", "综合课程", "研究课程"], "a": 2, "exp": "此题考查综合课程。根据综合程度的不同，综合课程分为相关课程、融合课程、广域课程、核心课程。依据知识点三第1题", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 4, "q": "从综合程度的不同来看，打破了学科界限，将若干相关学科内容融合成一门新学科的综合课程是（　）", "opts": ["联络课程", "融合课程", "广域课程", "轮形课程"], "a": 1, "exp": "此题考查融合课程。融合课程是指打破了学科界限，把有着内在联系的不同学科知识合并成一门课程。依据知识点三第1题", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 5, "q": "教育界尝试以综合课程来加强学科之间以及学科知识与现实生活之间的联系，典型的综合课程按照课程综合程度，由高到低排列为（．（　）", "opts": ["相关课程、广域课程、核心课程", "广域课程、相关课程、核心课程", "核心课程、相关课程、广域课程", "核心课程、广域课程、相关课程"], "a": 3, "exp": "此题考查综合课程。按照课程的综合程度，综合课程从高到低排列的顺序为核心课程、广域课程、融合课程、相关课程。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 6, "q": "某沿海城市在义务教育阶段的学校全面开设海洋教育课程。这种课程属于（　）", "opts": ["国家课程", "地方课程", "校本课程", "生本课程"], "a": 1, "exp": "此题考查地方课程。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 7, "q": "某地区有着古老的制陶历史，该地区的某学校凭借这一优势，在校外专家的帮助和校内师生的共同努力下，将陶艺教育从兴趣小组的活动形式，发展到全校的美术课堂中，深受各年级学生的喜爱。该校的陶艺教育课程属于（　）", "opts": ["国家课程", "广域课程", "地方课程", "校本课程"], "a": 3, "exp": "此题考查课程的类型。此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 8, "q": "某校开发了“人工智能与生活应用”课程。该课程要求学生以小组合作的形式，经历“提出问题一设计解决方案一编程实践验证一成果展示与反思”的完整过程。该课程属于（　）", "opts": ["基础型课程", "研究型课程", "融合课程", "拓展型课程"], "a": 1, "exp": "此题考查课程的类型。合研究型课程的特点。依据知识点三第1题解析，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 9, "q": "某语文教师以“乡愁”为主题设计了一堂课，学生在课上对比赏析了历代诗人的乡愁佳作，总结了乡愁诗中常见的意象。下课时，教师布置了以“乡愁”为主题的写作作业。从课程类型来看，这堂课属于（　）", "opts": ["分科课程", "相关课程", "核心课程", "校本课程"], "a": 0, "exp": "此题考查课程的类型。A.题干中的课程全部围绕语文学科展开，语文属于分科课程。√B.题干并未涉及两个及以上学科的联合教学，不属于相关课程。C.题干并不是以一个问题为核心，将各种学科知识综合起来的核心课程。D.题干并非学校自主研发与实施的校本课程，而是国家规定的必修语文课。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 10, "q": "将地理、历史、经济学、政治学、社会学、法学和人类学等学科的相关内容整合成“社会研究”课程，这种课程属于（　）", "opts": ["相关课程", "融合课程", "广域课程", "核心课程"], "a": 2, "exp": "此题考查广域课程。广域课程是指将各科教材依照性质归到各个领域，再将同一领域的各科教材加以组织和排列，进行系统教学的课程。与相关课程、融合课程相比，其综合范围更加广泛。题干中，“社会研究”课程将地理、历史、经济学等社会科学领域的相邻学科内容整合为一门课程，属于广域课程。依据知识点三第1题解析，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 11, "q": "关于核心课程的优点，以下说法错误的是（　）", "opts": ["强调内容的统一性和实用性", "课程内容来自周围的社会生活和问题，学生会产生相当强烈的内在动机", "通过积极的方式认识社会和改造社会", "强调课程内容的系统性和逻辑性"], "a": 3, "exp": "此题考查核心课程。核心课程丰富和拓宽了学习内容的内涵和外延，使学生获得综合应用知识的能力，强调课程内容的统一性和实用性，引起学生的内在动机，促进学生用积极的方式认识和改造社会。但是，课程的内容和顺序可能是凌乱的、琐碎的或肤浅的，学习单元可能是支离破碎的，知识的逻辑性、系统性会受到影响。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 153}},
  {"id": "kc|edu-principle|ep-06|知识点三|12", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 12, "q": "北京师范大学的校训“学为人师，行为世范”十分精炼地诠释了“师范”的意义，勉励师生“所学要为世人之师，所行应为世人之范”。这属于（　）", "opts": ["隐性课程", "活动课程", "综合课程", "国家课程"], "a": 0, "exp": "此题考查课程的类型。·校训是一种校园文化情境，具有感染与熏陶作用，可以潜移默化地影响学生的发展，属于隐性课程。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点三|13", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 13, "q": "下列关于义务教育劳动课程的说法，不正确的是（　）", "opts": ["劳动课程是国家课程", "劳动课程是选修课程", "劳动课程是活动课程", "劳动课程是显性课程"], "a": 1, "exp": "此题考查劳动课程。A.劳动课程必须按照国家规定的课程标准和教学要求进行，是国家课程。B.修改：劳动课程要求所有学生都必须修习，是必修课程。此题为选非题。√C.劳动课程注重学生的动手实践，是活动课程。D.劳动课程有明确的教学目标、教学安排和系统的教学内容，能够进行教学评价，是显性课程。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点三|14", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点三：课程类型", "no": 14, "q": "从课程功能来说，注重加强学生文学、艺术鉴赏方面的教育与拓展学生文化素质的文化素养课程和艺术团队活动，注重培养学生知识与社会实践相结合的能力和环境保护意识等方面的课程，属于（　）", "opts": ["基础型课程", "拓展型课程", "研究型课程", "轮形课程"], "a": 1, "exp": "此题考查拓展型课程。拓展型课程重在拓展学生的知识与能力，开阔学生的知识视野，发展学生各种不同的特殊能力，并将其迁移到其他方面知识的学习中。题干中提到的课程是典型的拓展型课程。依据知识点三第1题解析，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 1, "q": "基本模式·被称为课程领域中“主导的课程范式”的是（　）", "opts": ["泰勒原理", "教育目标分类学", "过程评价模式", "目标游离评价模式"], "a": 0, "exp": "此题考查泰勒原理。A.泰勒原理：被称为课程领域中“主导的课程范式”，是最有影响力的课程开发模式。√B.教育目标分类学：布卢姆建立了教育目标分类学，将教育目标分为认知领域、情感领域和动作技能领域。C.过程评价模式：对课程计划实施过程以及教学活动过程的评价。D.目标游离评价模式：评价的重点应从“课程计划预期的效果”转向“课程计划实际的结果”。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 2, "q": "泰勒的课程编制原理主要强调（　）", "opts": ["课程目标的主导作用", "教师对课程的再开发", "管理者对课程的监控", "学生对课程的评价"], "a": 0, "exp": "此题考查泰勒原理。A.课程目标的主导作用：泰勒的目标模式是以目标为导向来进行的，突出目标的核心作用。√B.教师对课程的再开发：斯腾豪斯的过程模式、施瓦布的实践模式都强调教师对课程的再开发。C.管理者对课程的监控：目标模式、过程模式和实践模式没有强调管理者的监控。建套课程公众号【研大】深联系微信1931637日8日D.学生对课程的评价：施瓦布的实践模式特别强调学生对课程的评价。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 3, "q": "在泰勒的课程开发模式中，有助于提高课程编制的科学性，使其成为动态的、开放的过程的环节是（　）", "opts": ["确定教育目标", "选择教育经验", "组织教育经验", "评价教育计划"], "a": 3, "exp": "此题考查泰勒的目标模式。A.确定教育目标：明确课程要达到的目标。B.选择教育经验：选择有助于达成目标的教育经验。C.组织教育经验：合理组织教育经验以优化教学效果。D.评价教育计划：可以及时发现课程目标设定、经验选择或组织过程中存在的问题，进而反向调整前面的各个环节，推动课程不断完善。这一过程具有开放性、灵活性、动态性。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 4, "q": "泰勒认为，教育目标的三个来源是（　）", "opts": ["对知识的研究、对学生的研究、学科专家对目标的建议", "对学生的研究、对当代社会生活的研究、学科专家对目标的建议", "对知识的研究、学科专家对目标的建议、对可行性的研究", "对学生经验的研究、对教育过程的研究、对当代社会生活的研究"], "a": 1, "exp": "此题考查泰勒的目标模式。泰勒认为，教育目标的三个来源分别是对学生的研究、对当代社会生活的研究以及学科专家对目标的建议。此题亦可通过推理作答。学科专家的主要作用是对知识的深刻研究，所以对知识的研究和学科专家对目标的建议其实有重合，A、C选项错误。泰勒属于知识中心课程理论流派，只有学习者中心才会重视教育过程的研究和学生经验的研究，D选项错误。B选项中三个要素是互斥的，没有重合现象。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 5, "q": "在课程开发模式中，追求课程的实践性，但因过于注重实践性、忽视理论而走向相对主义极端的是（　）", "opts": ["泰勒的目标模式", "施瓦布的实践模式", "斯腾豪斯的过程模式", "斯塔弗尔比姆的CIPP模式"], "a": 1, "exp": "此题考查施瓦布的实践模式。施瓦布的实践模式追求课程的实践性，但因过于注重实践性，忽视理论，走向了相对主义极端。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 6, "q": "关于课程开发，以下描述不正确的是（　）", "opts": ["斯腾豪斯与施瓦布都批判目标模式", "斯腾豪斯与施瓦布都主张对传统的“自下而上”的课程开发模式进行改革", "斯腾豪斯与施瓦布都强调要在具体的实践中开发课程", "斯腾豪斯与施瓦布的课程开发理论都为校本课程开发提供了理论依据"], "a": 1, "exp": "此题考查对课程开发基本模式的理解。斯腾豪斯的过程模式与施瓦布的实践模式都强调对传统的“自上而下”的课程决策模式进行变革。此", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 7, "q": "斯腾豪斯的过程模式对泰勒模式进行批判的主要依据是（　）", "opts": ["课程评价应该标准化", "教育活动要有内在价值", "教师角色应当技术化", "教育目标难以预先精确设定"], "a": 3, "exp": "此题考查斯腾豪斯的过程模式。A.斯腾豪斯的过程模式主张评价应是形成性的、过程性的，反对标准化评价。B.斯腾豪斯认为要关注教育活动的内在价值，但这并非其批判泰勒模式的主要依据。C.斯腾豪斯强调教师的角色是研究者和学习者，而非技术化的执行者。D.斯腾豪斯批判泰勒模式过于强调目标的预设性，忽视了教育过程中的不确定性和学生的主动性、创造性。√·主要产品", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 154}},
  {"id": "kc|edu-principle|ep-06|知识点四|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 8, "q": "主要产品。以下选项中的内容，按照从宏观到微观、从总体指导到具体操作的顺序排列的是（　）", "opts": ["课程标准、教科书、课程计划", "课程计划、课程标准、教科书", "课程标准、课程计划、教科书", "教科书、课程标准、课程计划"], "a": 1, "exp": "此题考查课程开发的主要产品。课程计划是课程的总体规划，课程标准和教科书是课程的具体体现，其中教科书是最具体的资料。因此，依据题干顺序排列为：课程计划、课程标准、教科书。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 9, "q": "制定课程计划的核心问题是（　）", "opts": ["学科设置", "课程顺序", "课时分配", "学年编制"], "a": 0, "exp": "此题考查课程计划。学科设置是课程计划的核心问题。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 10, "q": "（）不属于课程计划的范围。（　）", "opts": ["学科设置", "教学进度", "课时分配", "学年编制"], "a": 1, "exp": "此题考查课程计划。课程计划的内容包括学校的培养目标、学科设置（课程计划的核心问题）学科顺序、课时分配、学年编制和周学时安排等，不包括教学进度。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 11, "q": "根据2022年版义务教育新课标的总体导向，新课标提出的“学业质量标准”的主要功能是（　）", "opts": ["为教材编写提供详细的知识点列表", "为阶段性考试和升学考试命题提供主要依据", "刻画学生完成课程学习后核心素养应达到的水平", "作为教师年度绩效考核的指标"], "a": 2, "exp": "此题考查课程标准。新课标提出的“学业质量标准”不同于以往对知识掌握程度的简单描述，而是首次系统、明确地刻画了学生在完成各学段学习后，其核心素养应该发展到什么样的具体表现水平。这是“学业质量标准”在新课标中的准确定义和首要功能。它为教学和评价提供了清晰的“素养画像”，是新课标实现“素养导向”的关键创新。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|12", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 12, "q": "示”，细化了评价与考试命题建议，不仅明确了“为什么教”“教什么”，还明确了“教到什么程度”，这增强了课程标准的（　）", "opts": ["标准性", "客观性", "指导性", "纲领性"], "a": 2, "exp": "此题考查《义务教育课程方案和课程标准（2022年版）》中课程标准的变化。《义务教育课程方案和课程标准（2022年版）》指出关于课程标准的几点变化：强化了课程育人导向；优化了课程内容结构；研制了学业质量标准；增强了指导性；加强了学段衔接。题干中表明新课标不仅明确了“为什么教”“教什么”，还明确了“教到什么程度”，这体现了新课标具有更强的指导性。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|13", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 13, "q": "根据“三科统编教材”国家统一部署，到2026年秋季学期，义务教育阶段所有年级均需使用统编教材的科目是（　）", "opts": ["语文、数学、英语", "道德与法治、语文、历史", "科学、信息技术、艺术", "体育与健康、劳动、综合实践活动"], "a": 1, "exp": "记忆+积累题此题考查教材。道德与法治、语文、历史三科教材意识形态属性强，体现国家意志，因此由国家统一组织编写、审核和推广。这是当前教材建设领域最重要的国家政策之一。因此，答案选B。·布卢姆的教育目标分类学。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|14", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 14, "q": "布卢姆的教育目标分类学。科学课上有一道试题，要求学生“举出一种无机物的例子，并说明它为什么是无机物”。根据布卢姆的教育目标分类标准，该试题涉及认知领域教育目标中的（　）", "opts": ["记忆水平", "理解水平", "应用水平", "分析水平"], "a": 1, "exp": "此题考查布卢姆的教育目标分类学。A.记忆水平：记住所学的材料，包括对具体事实、方法、过程、概念和原理的回忆。题干强调的是对概念的解释，排除该选项。B.理解水平：领悟所学材料的意义，但并不一定将其与其他事物相联系，代表最低水平的理解，可使用的描述动词有解释、辨别、概括、举例等。题干中，科学课上的试题主要是要求学生举例并解释，涉及理解水平。√C.应用水平：将所学概念、规则、方法、规律和理论应用于新情境中的能力，代表较高水平的理解。D.分析水平：将整体材料分解为各个构成部分以理解其组织结构，以及将所学的零碎知识整合为知识体系的能力。它代表了比“应用水平”更高的智能水平。题干未涉及分解或整合，排除该选项。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|15", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 15, "q": "依据布卢姆教育目标分类学的要求，下列不适合作为教学目标的是（　）", "opts": ["通过本节课的学习，要求学生掌握人物描写的技巧与方法", "通过本节课的学习，培养学生的创新意识与批判思维能力", "通过本节课的学习，激发学生对传统文化的热爱之情", "通过本节课的学习，要求学生迅速无误地认出五个生字"], "a": 1, "exp": "此题考查布卢姆的教育目标分类学。布卢姆主张能够作为教学目标的项目，必须是通过短期教学可达到的、具体化的、可观察的、可测量的外显行为。A、C、D选项均为短期教学可完成的具体目标。学生的创新意识与批判思维能力不可能在短期的教学中得到提升，不是具体可行的教学目标。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|16", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 16, "q": "布卢姆将教育目标分为认知领域、动作技能领域、情感领域的目标，其中属于认知领域最高层次目标的是（　）", "opts": ["理解文章的大意，可以概括中心思想", "学会做一道题目，可以解决同一类题目", "阅读一篇文章或材料后，可以辨别作者的主观观点和事实", "根据一篇报告，要求学生想出解决问题的具体措施"], "a": 3, "exp": "此题考查布卢姆的教育目标分类学。布卢姆按照从简单到复杂的顺序将认知领域的教育目标分为六个层次：记忆、理解、应用、分析、评价、创造。：·A.理解文章的大意，可以概括中心思想，属于理解层次。B.学会做一道题目，可以解决同一类题目，这种“举一反三”的能力属于应用层次。C.阅读文章或材料后，辨别作者的观点和事实，属于理解层次。D.学生根据报告想出具体解决措施，属于创造层次。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 155}},
  {"id": "kc|edu-principle|ep-06|知识点四|17", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 17, "q": "刘老师在教授《穷人》的第二课时时，以三个问题贯穿整个课堂，分别是“本文中的哪些环境、人物动作等描写能反映出桑娜的心理感受？”“课文标题是《穷人》，桑娜和渔夫真的是穷人吗？你怎么看？”“本文中的环境描写非常优秀，你能模仿着写一个以景衬情的小故事吗？”根据布卢姆的教育目标分类学，刘老师在这节课中未涉及的认知目标是（　）", "opts": ["分析", "理解", "创造", "评价"], "a": 1, "exp": "此题考查布卢姆的教育目标分类学。布卢姆的教育目标分类学中的“理解”意为：领悟所学材料的意义，但并不一定将其与其他事物相联系，代表最低水平的理解。题干中的问题涉及对课文的深层分析，已经超过了“理解”的范畴，刘老师的三个问题分别体现了布卢姆的教育目标分类学中的“分析”“评价”与“创造”。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|18", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 18, "q": "学校组织参观红色革命纪念馆，馆内的展品和讲解员的讲述深深触动了同学们。在参观结束后的交流环节中，李娟同学率先发言，她声音中带着激动，主动表达了对革命先烈的崇敬之情。李娟的表现至少达到了布卢姆情感领域目标中的（　）", "opts": ["接受层次", "反应层次", "价值化层次", "价值体系个性化层次"], "a": 1, "exp": "此题考查布卢姆的教育目标分类学。A.接受层次：学生遵照教师的要求行事，但不一定认同。题干中，李娟主动表达崇敬之情，内心充满认同感，明显超越了这一层次。B.反应层次：学生认同并做出积极回应。题干中，李娟在参观完红色革命纪念馆后，通过语言和情绪主动表达自己的感受，这是对参观活动主动且积极的反馈，契合反应层次的要求。√C.价值化层次：学生形成较为稳定的价值判断。若李娟进一步将这种崇敬之情转化为长期行动（如定期参与红色教育活动），则可能达到价值化层次或更高层次。D.价值体系个性化层次：价值观已内化为稳定的人格特质（如生活中一贯以先烈精神自律）。题干仅为单次反应。：·课程的组织·", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|19", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 19, "q": "课程的组织若遇到对理论性要求较高、学生不易理解和掌握的内容，最好使用（）的方式组织课程内容。（　）", "opts": ["螺旋式", "逻辑顺序", "纵向组织", "横向组织"], "a": 0, "exp": "此题考查课程内容的组织形式。A.螺旋式：适用于对理论性要求较高、学生不易理解和掌握的内容，尤其对低年级的学生来说，螺旋式较合适。√B.逻辑顺序：根据学科本身的体系和知识的内在联系组织课程内容。C.纵向组织：注重课程内容的学科理论体系和学术性。D.横向组织：强调课程内容在社会生活中的实际运用和知识的综合性。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|20", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 20, "q": "学生在小学数学课程中通过测量或拼图学习三角形的内角和为180度，在中学数学课程中通过证明学习三角形的内角和为180度。这种课程内容的组织形式是（　）", "opts": ["直线式", "螺旋式", "纵向式", "横向式"], "a": 1, "exp": "此题考查课程内容的组织形式。采用螺旋式组织课程内容，即同一课程内容前后重复出现，前面呈现的内容是后面内容的基础，后面内容是对前面内容的不断扩展和加深，层层递进。题干中从小学通过测量或拼图得到三角形的内角和为180度，到中学通过原理证明这一结论，体现了螺旋式课程组织形式。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|21", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 21, "q": "布卢姆等人所著的《教育目标分类学》中认知领域教育目标的层次包括记忆、理解、应用、分析、评价、创造，强调学习内容由简单到复杂按顺序排列。这种课程内容的组织方式属于（　）", "opts": ["横向组织", "纵向组织", "螺旋式", "直线式"], "a": 1, "exp": "此题考查课程内容的组织形式。布卢姆的《教育目标分类学》将认知目标分为由简单到复杂的层次，强调学习内容按难度和复杂性逐步深人的顺序排列，这种组织方式属于纵向组织。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|22", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 22, "q": "某小学的“认识我们的社区”课程，融合了语文、美术、社会、劳动等多学科知识。这种课程主要体现了（　）的组织方式。（　）", "opts": ["学科中心", "纵向组织", "横向组织", "螺旋式组织"], "a": 2, "exp": "此题考查课程内容的组织形式。围绕“认识我们的社区”这一主题，将多门学科知识联系起来，强调课程内容在社会生活中的实际运用和知识的综合性，这属于横向组织。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|23", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 23, "q": "杜威主张“课程教材心理化”，强调将学科知识“还原”为儿童的生活经验，再引导其发展为系统知识。这一观点主要倡导的是（　）", "opts": ["以学科逻辑为起点，辅以心理逻辑", "以心理逻辑为主导，改造学科逻辑", "心理逻辑与学科逻辑并重，平行组织", "完全摒弃学科逻辑，遵从儿童本能"], "a": 1, "exp": "此题考查课程内容的组织形式。杜威的“课程教材心理化”并非不要学科知识，而是主张将学科知识转化为符合儿童心理经验的形式，所以他主张以心理逻辑为主导，改造学科逻辑。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点四|24", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点四：课程开发", "no": 24, "q": "“先学整数，再学小数和分数；先学加法，再学乘法”，这种课程内容编排主要遵循了（　）", "opts": ["直线式组织", "螺旋式组织", "横向组织", "社会问题组织"], "a": 0, "exp": "此题考查课程内容的组织形式。“先学整数，再学小数和分数；先学加法，再学乘法”，说明课程内容直线前进，前面安排过的内容在后面不再呈现，遵循了直线式组织形式。因此，答案选A。深联系微信1931637日8日", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 156}},
  {"id": "kc|edu-principle|ep-06|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点五：课程实施", "no": 1, "q": "衡量课程实施成功与否的基本标准是课程实施过程中实现预定的课程方案的程度，这属于（　）", "opts": ["缩减差距取向", "相互调试取向", "课程创生取向", "课程忠实取向"], "a": 3, "exp": "此题考查课程的忠实取向。A.缩减差距取向：通过各种方式，尽力缩小课程设计预期与课程实际实施情况之间的差距。B.相互调试取向：又称相互适应取向，教师将教材与其他教育资源相互调整和结合。C.课程创生取向：教师创新。D.课程忠实取向：教师忠实地执行教材。题干说明课程实施成功与否，课程实施过程中实现预定的课程方案的程度，属于课程的忠实取向。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点五|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点五：课程实施", "no": 2, "q": "在课程的实施过程中，努力使课程计划与班级或学校实践情境在课程目标、内容、方法、组织模式诸方面相互调整、改变，以促使双方彼此协调，这是课程实施的（　）", "opts": ["忠实取向", "相互适应取向", "创生取向", "创新取向"], "a": 1, "exp": "此题考查课程的相互适应取向。教材教学，又寻找教材以外的内容，做好课程计划与实际需要的相互调适。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点五|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点五：课程实施", "no": 3, "q": "从课程资源的视角看，现代教师不仅是课程资源的（），更是课程资源的（．．）“（　）", "opts": ["使用者；消费者．", "鉴别者；保管者．", "利用者；开发者", "接受者；传递者"], "a": 2, "exp": "此题考查课程资源的开发与利用。现代课程观强调，教师要有识别、利用各类资源的能力，即成为课程资源的利用者；更要能结合教学需要，主动创造、整合、生成新的课程资源，即成为课程资源的开发者。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点五|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点五：课程实施", "no": 4, "q": "某小学在筹备“校园趣味科学”课程时，先通过讨论和访谈收集了学生感兴趣的科学话题（如“彩虹的形成”“蚂蚁搬家的秘密”等），再据此开发了实验材料包、动画视频等课程资源。该课程资源开发的路径是基于（　）", "opts": ["学科立场", "地域特色", "学习规律", "学生立场"], "a": 3, "exp": "此题考查课程资源的开发与利用。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点六|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点六：课程评价（重点：课程评价模式）", "no": 1, "q": "分析课程方案中所反映的课程的基本要素是否具有科学性和可行性，需要了解课程的取向以及一门具体课程的基本特征。从对这些特征的分析中，了解一门课程或一套课程方案的适应性及其优点与不足。这体现了课程评价的（）功能。（　）", "opts": ["指导", "判断", "调整", "激发"], "a": 1, "exp": "此题考查课程评价的功能。课程评价具有诊断、导向、调控、激励、决策、修正的功能。题干中提到“了解一门课程或一套课程方案的适应性及其优点与不足”，体现了课程评价的判断功能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点六|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点六：课程评价（重点：课程评价模式）", "no": 2, "q": "认为评价主要是为决策者提供信息，包括背景评价、输入评价、过程评价、结果评价四种评价的课程评价模式是（　）", "opts": ["CIPP模式", "CSE评价模式", "综合评价模式", "反对者模式"], "a": 0, "exp": "此题考查CIPP模式。CIPP模式就是背景评价（ContextEvaluation）输人评价（InputEvaluation）过程评价（ProcessEvaluation）和结果评价（ProductEvaluation）。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点六|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点六：课程评价（重点：课程评价模式）", "no": 3, "q": "主张课程评价的重点从“课程计划预期的效果”转向“课程计划实际的结果”的课程评价模式是（　）", "opts": ["目标达成模式", "目标游离模式", "外观评价模式", "CIPP模式"], "a": 1, "exp": "此题考查目标游离模式。目标游离模式主张评价者应注意的是课程计划的实际效应，而不是其预期效应，评价的重点应从“课程计划预期的效果”转向“课程计划实际的结果”。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}}
]);
